import React from 'react';
import {Icon} from "../../components/icon/Icon";
import {FlexWrapper} from "../../components/FlexWrapper";
import {Container} from "../../components/Container";
import {S} from "./Footer_Styles"
import {FooterIcon} from "./FooterIcon";


const  socialItemData = [
    {
        iconId: "email",
        title: "gmail"
    },
    {
        iconId: "linkedin",
        title: "linkedin"
    },
    {
        iconId: "gitHub",
        title: "GITHUB"
    }
]

export const Footer: React.FC = () => {
    return (
        <S.Footer>
            <Container>
                <FlexWrapper direction={"column"} rowGap={"50px"}>
                    <S.SocialList>
                        {socialItemData.map((s, index) => {
                            return (
                                <S.SocialItem key={index}>
                                    <S.SocialList>
                                        <FooterIcon
                                            height={"38"}
                                            width={"38"}
                                            viewBox={"0 0 38 38"}
                                            iconId={s.iconId}
                                        />
                                    </S.SocialList>
                                    <S.SocialTitle>{s.title}</S.SocialTitle>
                                </S.SocialItem>
                            );
                        })}
                    </S.SocialList>
                    <S.BlockLink>
                        <S.SocialLink
                            activeClass="active"
                            to={"projects"}
                            smooth={true}
                            spy={true}
                            >Projects</S.SocialLink>
                        <S.SocialLink
                            activeClass="active"
                            to={"contact"}
                            smooth={true}
                            spy={true}
                           >Contact</S.SocialLink>
                    </S.BlockLink>
                    <S.Copyright>WEB DEVELOPER 2021</S.Copyright>
                </FlexWrapper>
            </Container>
        </S.Footer>
    );
};